import React, { useEffect, useMemo, useRef, useState } from "react";
import { AccessibilityInfo, PanResponder, View, type ViewStyle } from "react-native";
import { Canvas, Fill, Shader, Skia } from "@shopify/react-native-skia";
import { useDerivedValue, useFrameCallback, useSharedValue } from "react-native-reanimated";
import {
  PRISM_DEFAULTS,
  createPrism,
  prismDown,
  prismMove,
  prismRelease,
  prismStep,
  prismVertices,
  tracePrism,
  type PrismState,
  type PrismTrace,
} from "./prismMath";
import { BEAM_W, BEAM_Y, PRISM_BACKGROUND, PRISM_H, PRISM_REST_X, PRISM_REST_Y, PRISM_SIDE, PRISM_W } from "./prismDesign";
import { PRISM_SHADER } from "./prismShader";

export type PrismProps = {
  monochromatic?: boolean;
  reducedMotion?: boolean;
  onFeedback?: (event: "touch" | "release") => void;
  label?: string;
  style?: ViewStyle;
};

type Pointer = { x: number; y: number; down: number; seq: number };

const SKSL = `${PRISM_SHADER}
half4 main(float2 p) {
  return half4(half3(prismColor(p)), 1.0);
}
`;

let cachedEffect: ReturnType<typeof Skia.RuntimeEffect.Make> | undefined;
function getEffect() {
  if (cachedEffect === undefined) cachedEffect = Skia.RuntimeEffect.Make(SKSL);
  return cachedEffect;
}

function stillTrace(mono: boolean): PrismTrace {
  return tracePrism(0, BEAM_Y, 1, 0, PRISM_REST_X, BEAM_Y, PRISM_DEFAULTS.restTilt, PRISM_SIDE, mono);
}

// Android stops presenting a canvas whose only change is a shader uniform on an
// idle screen. A 1 px layout change every frame keeps it drawing.
function CanvasKeepAlive() {
  const [beat, setBeat] = useState(0);
  useEffect(() => {
    let cancelled = false;
    const tick = () => {
      if (cancelled) return;
      setBeat((b) => b + 1);
      requestAnimationFrame(tick);
    };
    const id = requestAnimationFrame(tick);
    return () => {
      cancelled = true;
      cancelAnimationFrame(id);
    };
  }, []);
  return (
    <View
      pointerEvents="none"
      style={{ position: "absolute", width: 1, height: 1, opacity: 0, transform: [{ translateX: beat % 2 }] }}
    />
  );
}

export function Prism({
  monochromatic = false,
  reducedMotion,
  onFeedback,
  label = "A glass prism you can drag through a light beam, splitting it into a rainbow",
  style,
}: PrismProps) {
  const [systemReduce, setSystemReduce] = useState(false);
  const reduce = reducedMotion ?? systemReduce;
  const opts = useMemo(() => PRISM_DEFAULTS, []);
  const effect = useMemo(() => getEffect(), []);
  const st = useSharedValue<PrismState>(createPrism(PRISM_REST_X, PRISM_REST_Y));
  const tr = useSharedValue<PrismTrace>(stillTrace(false));
  const frame = useSharedValue(0);
  const pointer = useSharedValue<Pointer>({ x: 0, y: 0, down: 0, seq: 0 });
  const monoM = useSharedValue(false);
  const reduceM = useSharedValue(false);
  const latest = useRef({ reduce, onFeedback, seq: 0 });
  latest.current.reduce = reduce;
  latest.current.onFeedback = onFeedback;

  useEffect(() => {
    let alive = true;
    AccessibilityInfo.isReduceMotionEnabled()
      .then((v) => {
        if (alive) setSystemReduce(v);
      })
      .catch(() => {});
    const sub = AccessibilityInfo.addEventListener("reduceMotionChanged", setSystemReduce);
    return () => {
      alive = false;
      sub.remove();
    };
  }, []);
  useEffect(() => {
    monoM.value = monochromatic;
  }, [monochromatic, monoM]);
  useEffect(() => {
    reduceM.value = reduce;
    if (reduce) {
      // Still picture: the prism sits in the beam with the spectrum showing.
      st.value = createPrism(PRISM_REST_X, BEAM_Y);
      tr.value = stillTrace(monoM.value);
      frame.value = frame.value + 1;
    } else {
      st.value = createPrism(PRISM_REST_X, PRISM_REST_Y);
    }
  }, [reduce, reduceM, st, tr, frame, monoM]);

  const pan = useMemo(() => {
    const send = (x: number, y: number, down: number) => {
      latest.current.seq += 1;
      pointer.value = { x, y, down, seq: latest.current.seq };
    };
    return PanResponder.create({
      onStartShouldSetPanResponder: () => !latest.current.reduce,
      onPanResponderGrant: (evt) => {
        send(evt.nativeEvent.locationX, evt.nativeEvent.locationY, 1);
        latest.current.onFeedback?.("touch");
      },
      onPanResponderMove: (evt) => {
        send(evt.nativeEvent.locationX, evt.nativeEvent.locationY, 1);
      },
      onPanResponderRelease: () => {
        send(pointer.value.x, pointer.value.y, 0);
        latest.current.onFeedback?.("release");
      },
      onPanResponderTerminate: () => {
        send(pointer.value.x, pointer.value.y, 0);
      },
      onPanResponderTerminationRequest: () => false,
    });
  }, [pointer]);

  useFrameCallback((info) => {
    if (reduceM.value) return;
    const s = st.value;
    const p = pointer.value;
    if (p.seq !== s.seq) {
      if (p.down && !s.down) prismDown(s, p.x, p.y);
      else if (p.down) prismMove(s, p.x, p.y);
      else prismRelease(s);
      s.seq = p.seq;
    }
    const dt = Math.min(48, info.timeSincePreviousFrame ?? 16.7) / 1000;
    prismStep(s, dt, opts);
    tr.value = tracePrism(0, BEAM_Y, 1, 0, s.x, s.y, s.tilt, PRISM_SIDE, monoM.value, opts);
    frame.value = frame.value + 1;
  });

  const uniforms = useDerivedValue(() => {
    frame.value;
    const s = st.value;
    const t = tr.value;
    const v = prismVertices(s.x, s.y, s.tilt, PRISM_SIDE);
    const lut = t.lut.length === 16 ? t.lut : new Array(16).fill(550);
    const seg = t.internal;
    return {
      size: [PRISM_W, PRISM_H],
      beam: [BEAM_Y, BEAM_W],
      triA: [v[0], v[1], v[2], v[3]],
      triC: [v[4], v[5]],
      incident: t.hit ? [0, BEAM_Y, t.entryX, t.entryY] : [0, BEAM_Y, PRISM_W, BEAM_Y],
      seg1: seg.length >= 4 ? [seg[0], seg[1], seg[2], seg[3]] : [0, 0, 0, 0],
      seg2: seg.length >= 6 ? [seg[2], seg[3], seg[4], seg[5]] : [0, 0, 0, 0],
      meta: [Math.max(0, seg.length / 2 - 1), t.hit ? 1 : 0],
      refl: [t.entryX, t.entryY, t.reflX, t.reflY],
      fan: [t.fanX, t.fanY, t.phi0, t.phi1],
      fanRef: [t.refDX, t.refDY],
      fanCfg: [t.fanOn ? 1 : 0, t.mono ? 1 : 0],
      lut0: [lut[0], lut[1], lut[2], lut[3]],
      lut1: [lut[4], lut[5], lut[6], lut[7]],
      lut2: [lut[8], lut[9], lut[10], lut[11]],
      lut3: [lut[12], lut[13], lut[14], lut[15]],
    };
  });

  return (
    <View
      style={[{ width: PRISM_W, height: PRISM_H, borderRadius: 18, overflow: "hidden", backgroundColor: PRISM_BACKGROUND }, style]}
      accessibilityLabel={label}
      accessibilityRole="image"
      {...pan.panHandlers}
    >
      {!reduce ? <CanvasKeepAlive /> : null}
      <Canvas pointerEvents="none" style={{ width: PRISM_W, height: PRISM_H }}>
        <Fill color={PRISM_BACKGROUND} />
        {effect ? (
          <Fill>
            <Shader source={effect} uniforms={uniforms} />
          </Fill>
        ) : null}
      </Canvas>
    </View>
  );
}

// A light beam through a glass prism. Snell's law per wavelength, dispersion
// from Cauchy's equation. Geometry in pixels, wavelengths in nanometres.

export const PRISM_DEFAULTS = {
  cauchyA: 1.5046, // crown glass, close to BK7
  cauchyB: 0.0042, // um^2
  lambdaMinNm: 380,
  lambdaMaxNm: 700,
  lambdaRefNm: 550,
  monoLambdaNm: 589, // sodium, roughly the middle of the eye's range
  fanSamples: 16,
  followOmega: 14,
  followDamping: 0.85,
  tiltOmega: 9,
  tiltDamping: 0.7,
  tiltPerVelocity: 0.0011,
  tiltMax: 0.05, // rad, about 3 degrees of lean while dragging
  restTilt: 0.0436, // rad, about +2.5 degrees: a wide fan, short of TIR
  fixedDt: 1 / 240,
};
export type PrismOptions = typeof PRISM_DEFAULTS;

// Cauchy's equation: n = A + B / lambda^2, lambda in micrometres.
export function cauchyN(lambdaNm: number, o: PrismOptions = PRISM_DEFAULTS) {
  "worklet";
  const um = lambdaNm / 1000;
  return o.cauchyA + o.cauchyB / (um * um);
}

// Vector Snell refraction. I is the unit incident direction, N the unit normal
// with dot(I, N) < 0. Returns the unit transmitted direction, or null on total
// internal reflection.
export function refractVec(
  ix: number, iy: number, nx: number, ny: number, n1: number, n2: number,
): [number, number] | null {
  "worklet";
  const eta = n1 / n2;
  const cosI = -(ix * nx + iy * ny);
  const k = 1 - eta * eta * (1 - cosI * cosI);
  if (k < 0) return null;
  const c = eta * cosI - Math.sqrt(k);
  return [eta * ix + c * nx, eta * iy + c * ny];
}

export function reflectVec(ix: number, iy: number, nx: number, ny: number): [number, number] {
  "worklet";
  const d = 2 * (ix * nx + iy * ny);
  return [ix - d * nx, iy - d * ny];
}

// Approximate RGB for a spectral wavelength (Bruton's mapping, gamma 0.8).
export function wavelengthToRGB(lambdaNm: number): [number, number, number] {
  "worklet";
  let r = 0;
  let g = 0;
  let b = 0;
  const l = lambdaNm;
  if (l >= 380 && l < 440) { r = -(l - 440) / 60; b = 1; }
  else if (l >= 440 && l < 490) { g = (l - 440) / 50; b = 1; }
  else if (l >= 490 && l < 510) { g = 1; b = -(l - 510) / 20; }
  else if (l >= 510 && l < 580) { r = (l - 510) / 70; g = 1; }
  else if (l >= 580 && l < 645) { r = 1; g = -(l - 645) / 65; }
  else if (l >= 645 && l <= 780) { r = 1; }
  else return [0, 0, 0];
  let f = 1;
  if (l < 420) f = 0.3 + (0.7 * (l - 380)) / 40;
  else if (l > 700) f = 0.3 + (0.7 * (780 - l)) / 80;
  const gam = 0.8;
  return [Math.pow(r * f, gam), Math.pow(g * f, gam), Math.pow(b * f, gam)];
}

// Vertices of an equilateral triangle, apex up at angle 0, k = 0 apex then
// counterclockwise in screen coordinates (y down).
export function prismVertices(cx: number, cy: number, angle: number, side: number): number[] {
  "worklet";
  const R = side / Math.sqrt(3);
  const out: number[] = [];
  for (let k = 0; k < 3; k++) {
    const a = angle - Math.PI / 2 + (k * 2 * Math.PI) / 3;
    out.push(cx + R * Math.cos(a), cy + R * Math.sin(a));
  }
  return out;
}

// t of the first hit of ray o + t d on segment a-b with u in [0,1], else -1.
function raySegment(
  ox: number, oy: number, dx: number, dy: number,
  ax: number, ay: number, bx: number, by: number,
): number {
  "worklet";
  const ex = bx - ax;
  const ey = by - ay;
  const den = dx * ey - dy * ex;
  if (Math.abs(den) < 1e-12) return -1;
  const t = ((ax - ox) * ey - (ay - oy) * ex) / den;
  const u = ((ax - ox) * dy - (ay - oy) * dx) / den;
  if (t > 1e-6 && u >= 0 && u <= 1) return t;
  return -1;
}

function signedAngle(ax: number, ay: number, bx: number, by: number) {
  "worklet";
  return Math.atan2(ax * by - ay * bx, ax * bx + ay * by);
}

export type PrismTrace = {
  hit: boolean;
  entryX: number;
  entryY: number;
  reflX: number;
  reflY: number;
  internal: number[]; // flat polyline of the reference path inside the glass
  fanOn: boolean;
  mono: boolean;
  fanX: number;
  fanY: number;
  refDX: number;
  refDY: number;
  phi0: number; // exit angle of the red end, relative to the reference ray
  phi1: number; // exit angle of the violet end
  lut: number[]; // wavelength at s = i/15 between phi0 and phi1
  bounces: number; // internal reflections of the reference path
};

// Trace a beam through the prism per wavelength. The entry point is geometric
// and shared by all wavelengths; inside, each wavelength refracts on its own.
// On total internal reflection the ray reflects once and tries the next face.
export function tracePrism(
  ox: number, oy: number, dx: number, dy: number,
  cx: number, cy: number, angle: number, side: number,
  mono: boolean,
  o: PrismOptions = PRISM_DEFAULTS,
): PrismTrace {
  "worklet";
  const none: PrismTrace = {
    hit: false, entryX: 0, entryY: 0, reflX: 1, reflY: 0, internal: [],
    fanOn: false, mono, fanX: 0, fanY: 0, refDX: 1, refDY: 0,
    phi0: 0, phi1: 0, lut: [], bounces: 0,
  };
  const v = prismVertices(cx, cy, angle, side);
  const gx = (v[0] + v[2] + v[4]) / 3;
  const gy = (v[1] + v[3] + v[5]) / 3;
  // Edges with outward normals.
  const ex: number[] = [];
  const ey: number[] = [];
  const nx: number[] = [];
  const ny: number[] = [];
  for (let k = 0; k < 3; k++) {
    const ax = v[2 * k];
    const ay = v[2 * k + 1];
    const bx = v[2 * ((k + 1) % 3)];
    const by = v[2 * ((k + 1) % 3) + 1];
    let ux = -(by - ay);
    let uy = bx - ax;
    const mx = (ax + bx) / 2 - gx;
    const my = (ay + by) / 2 - gy;
    if (ux * mx + uy * my < 0) {
      ux = -ux;
      uy = -uy;
    }
    const len = Math.hypot(ux, uy);
    ex.push(ax, ay, bx, by);
    nx.push(ux / len);
    ny.push(uy / len);
  }
  // Entry: nearest edge the beam hits from outside.
  let tBest = -1;
  let eBest = -1;
  for (let k = 0; k < 3; k++) {
    if (dx * nx[k] + dy * ny[k] >= 0) continue;
    const t = raySegment(ox, oy, dx, dy, ex[4 * k], ex[4 * k + 1], ex[4 * k + 2], ex[4 * k + 3]);
    if (t > 0 && (tBest < 0 || t < tBest)) {
      tBest = t;
      eBest = k;
    }
  }
  if (eBest < 0) return none;
  const px = ox + tBest * dx;
  const py = oy + tBest * dy;
  const refl = reflectVec(dx, dy, nx[eBest], ny[eBest]);

  const lambdas: number[] = [];
  if (mono) {
    lambdas.push(o.monoLambdaNm);
  } else {
    for (let i = 0; i <= 32; i++) lambdas.push(o.lambdaMinNm + ((o.lambdaMaxNm - o.lambdaMinNm) * i) / 32);
  }
  type Exit = { lam: number; ok: boolean; x: number; y: number; dx: number; dy: number };
  const exits: Exit[] = [];
  let refInternal: number[] = [];
  let bounces = 0;
  for (const lam of lambdas) {
    const n = cauchyN(lam, o);
    const tin = refractVec(dx, dy, nx[eBest], ny[eBest], 1, n);
    if (!tin) continue; // cannot happen entering glass
    let rx = tin[0];
    let ry = tin[1];
    let sx = px;
    let sy = py;
    let fromEdge = eBest;
    const path = [px, py];
    let out: [number, number] | null = null;
    let ox2 = sx;
    let oy2 = sy;
    let bounce = 0;
    for (let step = 0; step < 2 && !out; step++) {
      let tN = -1;
      let eN = -1;
      for (let k = 0; k < 3; k++) {
        if (k === fromEdge) continue;
        if (rx * nx[k] + ry * ny[k] <= 0) continue;
        const t = raySegment(sx, sy, rx, ry, ex[4 * k], ex[4 * k + 1], ex[4 * k + 2], ex[4 * k + 3]);
        if (t > 0 && (tN < 0 || t < tN)) {
          tN = t;
          eN = k;
        }
      }
      if (eN < 0) break;
      ox2 = sx + tN * rx;
      oy2 = sy + tN * ry;
      path.push(ox2, oy2);
      out = refractVec(rx, ry, -nx[eN], -ny[eN], n, 1);
      if (out) {
        exits.push({ lam, ok: true, x: ox2, y: oy2, dx: out[0], dy: out[1] });
      } else {
        const r = reflectVec(rx, ry, nx[eN], ny[eN]);
        rx = r[0];
        ry = r[1];
        sx = ox2;
        sy = oy2;
        fromEdge = eN;
        bounce++;
      }
    }
    if (!out) exits.push({ lam, ok: false, x: ox2, y: oy2, dx: rx, dy: ry });
    if (Math.abs(lam - (mono ? o.monoLambdaNm : o.lambdaRefNm)) < 1e-9) {
      refInternal = path;
      bounces = bounce;
    }
  }

  const okExits = exits.filter((e) => e.ok);
  const refLam = mono ? o.monoLambdaNm : o.lambdaRefNm;
  let ref = okExits.find((e) => Math.abs(e.lam - refLam) < 1e-9) ?? okExits[0];
  const base: PrismTrace = {
    ...none,
    hit: true,
    entryX: px,
    entryY: py,
    reflX: refl[0],
    reflY: refl[1],
    internal: refInternal,
    bounces,
  };
  if (!ref) return base;

  // Angles of the exiting rays relative to the reference ray.
  const withPhi = okExits.map((e) => ({
    lam: e.lam,
    phi: signedAngle(ref.dx, ref.dy, e.dx, e.dy),
  }));
  let phi0 = 0;
  let phi1 = 0;
  const lut: number[] = [];
  if (mono) {
    for (let i = 0; i < o.fanSamples; i++) lut.push(refLam);
  } else {
    const red = withPhi.reduce((a, b) => (a.lam > b.lam ? a : b));
    const violet = withPhi.reduce((a, b) => (a.lam < b.lam ? a : b));
    phi0 = red.phi;
    phi1 = violet.phi;
    const sorted = [...withPhi].sort((a, b) => a.phi - b.phi);
    for (let i = 0; i < o.fanSamples; i++) {
      const target = phi0 + ((phi1 - phi0) * i) / (o.fanSamples - 1);
      let lam = sorted[0].lam;
      for (let j = 0; j < sorted.length - 1; j++) {
        const a = sorted[j];
        const b2 = sorted[j + 1];
        const lo = Math.min(a.phi, b2.phi);
        const hi = Math.max(a.phi, b2.phi);
        if (target >= lo && target <= hi) {
          const f = (target - a.phi) / (b2.phi - a.phi || 1e-12);
          lam = a.lam + (b2.lam - a.lam) * f;
          break;
        }
        lam = target < lo ? sorted[0].lam : sorted[sorted.length - 1].lam;
      }
      lut.push(lam);
    }
  }
  return {
    ...base,
    fanOn: true,
    fanX: ref.x,
    fanY: ref.y,
    refDX: ref.dx,
    refDY: ref.dy,
    phi0,
    phi1,
    lut,
  };
}

export type PrismState = {
  x: number;
  y: number;
  vx: number;
  vy: number;
  tx: number;
  ty: number;
  gx: number;
  gy: number;
  tilt: number;
  tiltv: number;
  down: number;
  seq: number;
};

export function createPrism(x: number, y: number): PrismState {
  "worklet";
  return { x, y, vx: 0, vy: 0, tx: x, ty: y, gx: 0, gy: 0, tilt: PRISM_DEFAULTS.restTilt, tiltv: 0, down: 0, seq: 0 };
}
export function prismDown(st: PrismState, x: number, y: number) {
  "worklet";
  if (!st.down) {
    st.gx = st.x - x;
    st.gy = st.y - y;
  }
  st.down = 1;
  st.tx = x;
  st.ty = y;
}
export function prismMove(st: PrismState, x: number, y: number) {
  "worklet";
  st.tx = x;
  st.ty = y;
}
export function prismRelease(st: PrismState) {
  "worklet";
  st.down = 0;
}
// Advance the follow and tilt springs. Returns true while anything moves.
export function prismStep(st: PrismState, dt: number, o: PrismOptions = PRISM_DEFAULTS) {
  "worklet";
  const n = Math.max(1, Math.ceil(dt / o.fixedDt));
  const h = dt / n;
  for (let i = 0; i < n; i++) {
    if (st.down) {
      const tx2 = st.tx + st.gx;
      const ty2 = st.ty + st.gy;
      st.vx += (o.followOmega * o.followOmega * (tx2 - st.x) - 2 * o.followDamping * o.followOmega * st.vx) * h;
      st.vy += (o.followOmega * o.followOmega * (ty2 - st.y) - 2 * o.followDamping * o.followOmega * st.vy) * h;
      st.x += st.vx * h;
      st.y += st.vy * h;
    } else {
      const decay = Math.exp(-2 * o.followDamping * o.followOmega * h);
      st.vx *= decay;
      st.vy *= decay;
      st.x += st.vx * h;
      st.y += st.vy * h;
    }
    let target = o.restTilt;
    if (st.down) {
      const lean = st.vx * o.tiltPerVelocity;
      target += Math.max(-o.tiltMax, Math.min(o.tiltMax, lean));
    }
    st.tiltv += (o.tiltOmega * o.tiltOmega * (target - st.tilt) - 2 * o.tiltDamping * o.tiltOmega * st.tiltv) * h;
    st.tilt += st.tiltv * h;
  }
  return (
    st.down === 1 ||
    Math.abs(st.vx) > 0.05 ||
    Math.abs(st.vy) > 0.05 ||
    Math.abs(st.tiltv) > 1e-4 ||
    Math.abs(st.tilt - o.restTilt) > 1e-4
  );
}

import { SCREEN_X } from "./prismDesign";

// One shader draws the scene: dark bench, glass triangle, incident beam, the
// path inside the glass, the dispersed fan and a matte screen the fan lands
// on. All angles and wavelengths come from prismMath.ts.
export const PRISM_SHADER = `
uniform float2 size;
uniform float2 beam;      // y and full width
uniform float4 triA;      // v0.xy, v1.xy
uniform float2 triC;      // v2.xy
uniform float4 incident;  // beam start -> entry (or right edge)
uniform float4 seg1;      // internal reference path, first segment
uniform float4 seg2;      // internal reference path, second segment
uniform float2 meta;      // x: segment count, y: hit flag
uniform float4 refl;      // reflected stub at the entry face: point, dir * len
uniform float4 fan;       // exit point, phi red end, phi violet end
uniform float2 fanRef;    // reference exit direction
uniform float2 fanCfg;    // fan on, monochromatic
uniform float4 lut0;
uniform float4 lut1;
uniform float4 lut2;
uniform float4 lut3;

float segDist(float2 p, float2 a, float2 b) {
  float2 ab = b - a;
  float t = clamp(dot(p - a, ab) / max(dot(ab, ab), 1e-6), 0.0, 1.0);
  return length(p - a - ab * t);
}

float beamSeg(float2 p, float2 a, float2 b, float w) {
  float d = segDist(p, a, b);
  return exp(-(d * d) / (w * w));
}

float3 wavelengthRGB(float l) {
  float r = 0.0;
  float g = 0.0;
  float b = 0.0;
  if (l >= 380.0 && l < 440.0) { r = -(l - 440.0) / 60.0; b = 1.0; }
  else if (l >= 440.0 && l < 490.0) { g = (l - 440.0) / 50.0; b = 1.0; }
  else if (l >= 490.0 && l < 510.0) { g = 1.0; b = -(l - 510.0) / 20.0; }
  else if (l >= 510.0 && l < 580.0) { r = (l - 510.0) / 70.0; g = 1.0; }
  else if (l >= 580.0 && l < 645.0) { r = 1.0; g = -(l - 645.0) / 65.0; }
  else if (l >= 645.0 && l <= 780.0) { r = 1.0; }
  float f = 1.0;
  if (l < 420.0) f = 0.3 + 0.7 * (l - 380.0) / 40.0;
  else if (l > 700.0) f = 0.3 + 0.7 * (780.0 - l) / 80.0;
  return pow(float3(r * f, g * f, b * f), float3(0.8));
}

float lutAt(float s) {
  float x = clamp(s, 0.0, 1.0) * 15.0;
  float f = fract(x);
  int i = int(floor(x));
  if (i == 0) return mix(lut0.x, lut0.y, f);
  if (i == 1) return mix(lut0.y, lut0.z, f);
  if (i == 2) return mix(lut0.z, lut0.w, f);
  if (i == 3) return mix(lut0.w, lut1.x, f);
  if (i == 4) return mix(lut1.x, lut1.y, f);
  if (i == 5) return mix(lut1.y, lut1.z, f);
  if (i == 6) return mix(lut1.z, lut1.w, f);
  if (i == 7) return mix(lut1.w, lut2.x, f);
  if (i == 8) return mix(lut2.x, lut2.y, f);
  if (i == 9) return mix(lut2.y, lut2.z, f);
  if (i == 10) return mix(lut2.z, lut2.w, f);
  if (i == 11) return mix(lut2.w, lut3.x, f);
  if (i == 12) return mix(lut3.x, lut3.y, f);
  if (i == 13) return mix(lut3.y, lut3.z, f);
  if (i == 14) return mix(lut3.z, lut3.w, f);
  return lut3.w;
}

float3 prismColor(float2 p) {
  float t = clamp(p.y / size.y, 0.0, 1.0);
  float3 col = mix(float3(0.016, 0.022, 0.045), float3(0.030, 0.040, 0.075), t);
  float2 vg = (p - size * 0.5) / size;
  col *= 1.0 - 0.5 * dot(vg, vg);

  // Matte screen the spectrum lands on.
  float sx = ${SCREEN_X}.0;
  float scr = smoothstep(2.0, 0.0, abs(p.x - sx) - 3.0) * step(20.0, p.y) * step(p.y, size.y - 20.0);
  col = mix(col, float3(0.62, 0.66, 0.72) * (0.55 + 0.45 * t), scr * 0.85);

  // Glass triangle: faint fill and a bright rim.
  float2 v0 = triA.xy;
  float2 v1 = triA.zw;
  float2 v2 = triC;
  float d0 = segDist(p, v0, v1);
  float d1 = segDist(p, v1, v2);
  float d2 = segDist(p, v2, v0);
  float dE = min(d0, min(d1, d2));
  float c0 = (v1.x - v0.x) * (p.y - v0.y) - (v1.y - v0.y) * (p.x - v0.x);
  float c1 = (v2.x - v1.x) * (p.y - v1.y) - (v2.y - v1.y) * (p.x - v1.x);
  float c2 = (v0.x - v2.x) * (p.y - v2.y) - (v0.y - v2.y) * (p.x - v2.x);
  bool inside = (c0 >= 0.0 && c1 >= 0.0 && c2 >= 0.0) || (c0 <= 0.0 && c1 <= 0.0 && c2 <= 0.0);
  if (inside) {
    col += float3(0.45, 0.60, 0.78) * 0.045;
    col += float3(0.55, 0.75, 1.0) * 0.10 * exp(-dE / 9.0);
  }
  col += float3(0.60, 0.78, 1.0) * 0.30 * exp(-abs(dE) / 2.0);

  float w = beam.y * 0.5;

  // Incident beam, white with a soft halo.
  float bi = beamSeg(p, incident.xy, incident.zw, w);
  col += float3(1.0, 0.99, 0.95) * bi * 0.85;
  col += float3(1.0, 0.98, 0.92) * beamSeg(p, incident.xy, incident.zw, w * 2.6) * 0.10;

  if (meta.y > 0.5) {
    // Faint reflection off the entry face.
    float2 rEnd = refl.xy + refl.zw * 60.0;
    col += float3(1.0, 0.99, 0.95) * beamSeg(p, refl.xy, rEnd, w * 0.55) * 0.14;
    // The reference path inside the glass.
    float i1 = beamSeg(p, seg1.xy, seg1.zw, w * 0.5);
    col += float3(0.92, 0.96, 1.0) * i1 * 0.55;
    if (meta.x > 1.5) {
      float i2 = beamSeg(p, seg2.xy, seg2.zw, w * 0.5);
      col += float3(0.92, 0.96, 1.0) * i2 * 0.45;
    }
  }

  if (fanCfg.x > 0.5) {
    float2 v = p - fan.xy;
    float d = length(v);
    if (d > 2.0) {
      float2 dir = v / d;
      float cs = clamp(dot(dir, fanRef), -1.0, 1.0);
      float sn = fanRef.x * dir.y - fanRef.y * dir.x;
      float phi = atan(sn, cs);
      float fade = exp(-d / 340.0);
      if (fanCfg.y > 0.5) {
        float perp = abs(d * sin(phi));
        float inten = exp(-(perp * perp) / (w * w * 0.55 * 0.55)) * fade;
        col += wavelengthRGB(lut0.x) * inten;
        col += wavelengthRGB(lut0.x) * exp(-(perp * perp) / (w * w * 2.6 * 2.6)) * fade * 0.10;
      } else {
        float spread = fan.w - fan.z;
        float s = (phi - fan.z) / spread;
        float lam = lutAt(s);
        float exc = s < 0.0 ? -s : (s > 1.0 ? s - 1.0 : 0.0);
        float inten = exp(-pow(exc * spread * d / (w * 0.55), 2.0)) * fade;
        col += wavelengthRGB(lam) * inten * 1.1;
      }
    }
    // Glow where the beam leaves the glass.
    col += float3(1.0, 0.98, 0.94) * exp(-d / 7.0) * 0.22;
  }

  col = col / (1.0 + col * 0.30);
  return pow(col, float3(0.95));
}
`;

export const PRISM_W = 320;
export const PRISM_H = 340;
export const PRISM_BACKGROUND = "#05070d";
export const PRISM_SIDE = 100;
export const BEAM_Y = 140;
export const BEAM_W = 9;
export const SCREEN_X = 296;
// Resting spot, below the beam so the beam passes over the prism.
export const PRISM_REST_X = 160;
export const PRISM_REST_Y = 252;

import React, { useState } from "react";
import { Pressable, Text, View } from "react-native";
import { Prism } from "./Prism";

export default function Example({ onFeedback }: { onFeedback?: (event: "touch" | "release") => void }) {
  const [mono, setMono] = useState(false);
  const chip = (on: boolean) => ({
    paddingVertical: 9, paddingHorizontal: 13, borderRadius: 24, borderWidth: 1,
    backgroundColor: on ? "#315843" : "#eeeade", borderColor: on ? "#315843" : "#c7caba",
  });
  return (
    <View style={{ alignItems: "center", gap: 10, paddingVertical: 14 }}>
      <Prism monochromatic={mono} onFeedback={onFeedback} />
      <View style={{ flexDirection: "row", gap: 8 }}>
        <Pressable accessibilityRole="switch" accessibilityState={{ checked: mono }} onPress={() => setMono((v) => !v)} style={chip(mono)}>
          <Text style={{ fontSize: 12, color: mono ? "#fff" : "#315843", fontFamily: "Geist-Regular" }}>Light: {mono ? "sodium 589 nm" : "white"}</Text>
        </Pressable>
      </View>
      <Text style={{ fontSize: 12, color: "#63705f", fontFamily: "Geist-Regular" }}>Drag the prism into the beam. White light splits; a single colour only bends.</Text>
    </View>
  );
}
